error_log stderr;
pid nginx.pid;
events { worker_connections 64; }
http { access_log off;
client_body_temp_path client_body; proxy_temp_path proxy;
fastcgi_temp_path fastcgi; uwsgi_temp_path uwsgi; scgi_temp_path scgi;
