initial.nginx:
master_process on;
worker_processes 1;
daemon off;
error_log stderr;
pid nginx.pid;
events { worker_connections 64; }
http { access_log off;
client_body_temp_path client_body; proxy_temp_path proxy;
fastcgi_temp_path fastcgi; uwsgi_temp_path uwsgi; scgi_temp_path scgi;
server { listen 127.0.0.1:64750; server_name compat.test;
        location /public { return 200 public; }
        location /private {
            internal;
            return 200 private;
            location /private/child { return 200 "$request_method|$host|$uri|$args|$scheme|$remote_addr"; }
        }
        location /enter { rewrite ^ /private/child last; }
        location /guarded { internal; rewrite ^ /public last; }
        location /toggle { add_header X-Generation one; return 200 toggle; }
    }
}

reload.nginx:
master_process on;
worker_processes 1;
daemon off;
error_log stderr;
pid nginx.pid;
events { worker_connections 64; }
http { access_log off;
client_body_temp_path client_body; proxy_temp_path proxy;
fastcgi_temp_path fastcgi; uwsgi_temp_path uwsgi; scgi_temp_path scgi;
server { listen 127.0.0.1:64750; server_name compat.test;
        location /public { return 200 public; }
        location /private {
            internal;
            return 200 private;
            location /private/child { return 200 "$request_method|$host|$uri|$args|$scheme|$remote_addr"; }
        }
        location /enter { rewrite ^ /private/child last; }
        location /guarded { internal; rewrite ^ /public last; }
        location /toggle { internal; return 200 toggle; }
    }
}
